const crypto = require('crypto');
const secret = $env.N8N_WEBHOOK_SECRET;
if (!secret) { throw new Error('N8N_WEBHOOK_SECRET is not set'); }
const item = $input.first();
const headers = (item.json && item.json.headers) || {};
const ts = headers['x-lit-timestamp'];
const eventId = headers['x-lit-event-id'];
const signature = headers['x-lit-signature'];
if (!ts || !eventId || !signature) { throw new Error('Missing signing headers'); }
const body = (item.json && item.json.body) !== undefined ? item.json.body : {};
const rawBody = typeof body === 'string' ? body : JSON.stringify(body);
const mac = crypto.createHmac('sha256', secret).update(ts + '.' + eventId + '.' + rawBody).digest('hex');
const expected = 'v1=' + mac;
const a = Buffer.from(expected);
const b = Buffer.from(String(signature));
const matches = a.length === b.length && crypto.timingSafeEqual(a, b);
if (!matches) { throw new Error('Signature verification failed'); }
const nowSec = Math.floor(Date.now() / 1000);
if (Math.abs(nowSec - Number(ts)) > 300) { throw new Error('Signature timestamp outside tolerance'); }
return [{ json: { verified: true, eventId, timestamp: ts, body } }];

const item = $input.first().json;
const payload = (item.body && item.body.payload) ? item.body.payload : (item.body || {});
const text = JSON.stringify(payload).toLowerCase();

// Zero-Trust Non-PHI Check: Strictly reject prescription data, patient identifiers, or clinical diagnoses
const phiKeywords = ['prescription', 'patient', 'patient_id', 'mrn', 'diagnosis', 'symptom', 'treatment plan', 'blood test', 'biopsy', 'radiology', 'mri scan', 'ehr record', 'patient record', 'hiv', 'oncology', 'doctor notes', 'vitals', 'clinical_notes', 'patient_name', 'dob', 'birth_date', 'aadhaar', 'ssn', 'icd10', 'rx', 'dosage_instructions'];
const containsPhi = phiKeywords.some(keyword => text.includes(keyword));

const facilityId = String(payload.facilityId || payload.facility_id || '').trim();
const skuId = String(payload.skuId || payload.itemCode || payload.sku || '').trim();
const itemName = String(payload.itemName || payload.itemDescription || 'Standard Medical Formulation').trim();
const batchNumber = String(payload.batchNumber || payload.lotNumber || 'BATCH-PROV').trim();
const currentStock = Number(payload.currentStock !== undefined ? payload.currentStock : (payload.quantity || 0));
const reorderThreshold = Number(payload.reorderThreshold || payload.minThreshold || 50);
const reorderQuantity = Number(payload.reorderQuantity || payload.targetReorderUnits || 100);
const supplierId = String(payload.supplierId || payload.vendorCode || 'SUPPLIER_CENTRAL').trim();
const unitOfMeasure = String(payload.unitOfMeasure || payload.uom || 'units').trim();

let urgencyLevel = 'STANDARD_REORDER';
if (currentStock <= 0) {
  urgencyLevel = 'STOCKOUT_CRITICAL';
} else if (currentStock < (reorderThreshold / 2)) {
  urgencyLevel = 'URGENT';
}

const isValidReorder = Boolean(facilityId && skuId && reorderQuantity > 0 && !containsPhi);

return [{
  json: {
    eventId: item.eventId,
    verified: item.verified,
    containsPhi,
    isValidReorder,
    inventory: {
      facilityId,
      skuId,
      itemName,
      batchNumber,
      currentStock,
      reorderThreshold,
      reorderQuantity,
      supplierId,
      unitOfMeasure,
      urgencyLevel,
      timestamp: new Date().toISOString()
    }
  }
}];

const item = $input.first().json;
const inv = item.inventory;
const cleanSku = inv.skuId.replace(/[^a-zA-Z0-9]/g, '').substring(0, 10).toUpperCase();
const poNumber = `PO-${cleanSku}-${Math.floor(Date.now() / 1000)}`;

const purchaseOrder = {
  poNumber,
  facilityId: inv.facilityId,
  supplierId: inv.supplierId,
  skuId: inv.skuId,
  itemDescription: inv.itemName,
  reorderQuantity: inv.reorderQuantity,
  unitOfMeasure: inv.unitOfMeasure,
  urgencyLevel: inv.urgencyLevel,
  currentStockCount: inv.currentStock,
  approvalStatus: 'PENDING_CHIEF_PHARMACIST_SIGNATURE',
  pharmacistReviewQueue: 'Hospital Inpatient Pharmacy Central Dispensing Hub',
  compliancePerimeter: 'Zero-Trust Non-PHI Inventory Automation (SKU ID & Stock Levels Only)',
  generatedAt: new Date().toISOString()
};

return [{
  json: {
    eventId: item.eventId,
    status: 'pharmacy_reorder_po_generated',
    detail: {
      poNumber,
      facilityId: inv.facilityId,
      skuId: inv.skuId,
      purchaseOrder,
      generatedAt: new Date().toISOString()
    }
  }
}];

const item = $input.first().json;
return [{
  json: {
    eventId: item.eventId,
    status: 'pharmacy_reorder_rejected',
    detail: {
      error: item.containsPhi
        ? 'CRITICAL_SECURITY_BREACH: Prohibited PHI or prescription data detected in pharmacy inventory payload'
        : 'Invalid pharmacy inventory parameters: missing facilityId, skuId, or reorderQuantity'
    }
  }
}];

const crypto = require('crypto');
const secret = $env.N8N_WEBHOOK_SECRET;
if (!secret) { throw new Error('N8N_WEBHOOK_SECRET is not set'); }
const item = $input.first();
const eventId = item.json.eventId;
const ts = String(Math.floor(Date.now() / 1000));
const payload = {
  eventId,
  status: item.json.status || 'processed',
  detail: item.json.detail || {}
};
const rawBody = JSON.stringify(payload);
const mac = crypto.createHmac('sha256', secret).update(ts + '.' + eventId + '.' + rawBody).digest('hex');
return [{ json: { eventId, status: payload.status, rawBody, timestamp: ts, signature: 'v1=' + mac } }];
